import json

from obligations import extract

EXPECTED = [
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "Vendor shall deliver the licensed software within thirty days of the Effective Date.",
    },
    {
        "party": "Customer",
        "modal": "must",
        "sentence": "Customer must pay the annual license fee within fifteen days of receiving an invoice.",
    },
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "Vendor shall provide technical support during normal business hours",
    },
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "shall remediate critical defects within four hours of report.",
    },
    {
        "party": "UNATTRIBUTED",
        "modal": "must",
        "sentence": "Any dispute arising under this Agreement must be submitted to arbitration seated in Delaware and administered only by the Vendor.",
    },
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "Vendor shall maintain insurance coverage of not less than two million dollars throughout the term.",
    },
    {
        "party": "Customer",
        "modal": "shall",
        "sentence": "Customer shall use the software solely for internal business purposes.",
    },
    {
        "party": "UNATTRIBUTED",
        "modal": "must",
        "sentence": "Upon expiry all confidential materials must be returned or destroyed",
    },
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "the Vendor shall certify destruction within ten days.",
    },
    {
        "party": "Vendor",
        "modal": "shall",
        "sentence": "Vendor shall not assign this Agreement without the prior written consent of Customer.",
    },
    {
        "party": "UNATTRIBUTED",
        "modal": "shall",
        "sentence": "Neither party shall be liable for consequential damages exceeding the fees paid hereunder.",
    },
]


def test_exact_extraction():
    with open("fixture_agreement.txt", encoding="utf-8") as f:
        text = f.read()
    assert extract(text) == EXPECTED


def test_json_output_shape():
    with open("fixture_agreement.txt", encoding="utf-8") as f:
        text = f.read()
    result = json.loads(json.dumps(extract(text)))
    assert all(set(e) == {"party", "modal", "sentence"} for e in result)


def test_word_boundary_shallow_not_matched():
    with open("fixture_agreement.txt", encoding="utf-8") as f:
        text = f.read()
    assert not any("shallow" in e["sentence"] and e["modal"] != "shall" for e in extract(text))
    assert all(e["modal"] in ("shall", "must") for e in extract(text))

